<time datetime="2026-09-25T13:01:15+02:00" title="Vendredi 25 septembre 2026 - 13:01">ven 25/09/2026 - 13:01</time>
    <style>
  .video-iframe-container {
    display: flex;
    gap: 20px;
    width: 100%;
    align-items: flex-start;
  }

  .video-iframe-vimeo {
    flex: 2;
    position: relative;
    aspect-ratio: 16 / 9;
  }

  .video-iframe-slido {
    flex: 1;
    position: relative;
  }

  .video-iframe-container iframe {
    width: 100%;
    border: 0;
  }

  .video-iframe-vimeo iframe {
    height: 100%;
    width: 100%;
  }

  .video-iframe-slido iframe {
    height: 600px;
  }

  @media (max-width: 768px) {
    .video-iframe-container {
      flex-direction: column;
    }

    .video-iframe-vimeo,
    .video-iframe-slido {
      width: 100%;
    }
  }
</style><div class="video-iframe-container"><!-- Vimeo --><div class="video-iframe-vimeo"><iframe src="https://vimeo.com/event/6213744/embed/220855da06" frameborder="0" allow="autoplay; fullscreen; picture-in-picture; encrypted-media; web-share" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe></div><!-- Slido --><div class="video-iframe-slido"><iframe src="https://app.sli.do/event/m88gEju5ThG9JHGwVZMJQs" width="100%" height="600" frameborder="0"></iframe></div></div>      <img loading="lazy" src="https://www.afd.fr/sites/default/files/styles/header_content/public/2026-07/turquie-2024_0.jpg.webp?itok=GVw43S_b" width="792" height="450" alt="visuel conférence de recherche ">


